def build_sunspec_device(*models: SunSpecModel | dict[str, Any], **by_id: SunSpecModel | dict[str, Any]) -> SunSpecDevice:
    """Assemble a :class:`SunSpecDevice` from model instances or ``{model_id: payload}`` keywords.

    Positional arguments must be model instances (their ``MODEL_ID`` is the key). Keyword
    arguments are keyed by model id as a string, for example ``build_sunspec_device(**{"701": {...}})``.
    """
    payload: dict[int, Any] = {}
    for model in models:
        if isinstance(model, SunSpecModel):
            payload[model.ID if model.ID is not None else model.MODEL_ID] = model
        elif isinstance(model, dict) and model.get("ID") is not None:
            payload[int(model["ID"])] = model
        else:
            raise ValueError('Positional models must be SunSpecModel instances or dicts with an ID')
    for key, value in by_id.items():
        payload[int(key)] = value
    return SunSpecDevice.model_validate(payload)


